/* ============================================
   DRAWER COMPONENT
   Edge-anchored modal panel that slides in
   ============================================ */

.ds-drawer {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  visibility: hidden; /* keeps panel controls out of the tab order when closed */
  pointer-events: none;
  transition: visibility var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-drawer--open {
  visibility: visible;
  pointer-events: auto;
}

/* Anchor the panel to the requested edge */
.ds-drawer--left {
  justify-content: flex-start;
  align-items: stretch;
}

.ds-drawer--right {
  justify-content: flex-end;
  align-items: stretch;
}

.ds-drawer--top {
  align-items: flex-start;
  justify-content: stretch;
}

.ds-drawer--bottom {
  align-items: flex-end;
  justify-content: stretch;
}

/* ============================================
   SCRIM
   ============================================ */

.ds-drawer__scrim {
  position: absolute;
  inset: 0;
  background-color: var(--color-scrim);
  opacity: 0;
  transition: opacity var(--motion-duration-slow) var(--motion-ease-standard);
}

.ds-drawer--open .ds-drawer__scrim {
  opacity: 1;
}

/* ============================================
   PANEL
   ============================================ */

.ds-drawer__panel {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: var(--gap-400); /* 16px */
  padding: var(--padding-500); /* 20px */
  background-color: var(--color-bg-page-primary);
  box-shadow: var(--shadow-modal);
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
  outline: none;
  overflow: hidden;
}

/* Edge-specific border + resting (off-screen) transform */
.ds-drawer--left .ds-drawer__panel {
  height: 100%;
  border-right: var(--border-025) solid var(--color-bg-container-border);
  transform: translateX(-100%);
}

.ds-drawer--right .ds-drawer__panel {
  height: 100%;
  border-left: var(--border-025) solid var(--color-bg-container-border);
  transform: translateX(100%);
}

.ds-drawer--top .ds-drawer__panel {
  width: 100%;
  border-bottom: var(--border-025) solid var(--color-bg-container-border);
  transform: translateY(-100%);
}

.ds-drawer--bottom .ds-drawer__panel {
  width: 100%;
  border-top: var(--border-025) solid var(--color-bg-container-border);
  transform: translateY(100%);
}

.ds-drawer--open .ds-drawer__panel {
  transform: translate(0, 0);
}

/* ============================================
   SIZES — measured along the slide axis
   ============================================ */

.ds-drawer--left.ds-drawer--sm .ds-drawer__panel,
.ds-drawer--right.ds-drawer--sm .ds-drawer__panel {
  width: 320px;
  max-width: 100vw;
}

.ds-drawer--left.ds-drawer--md .ds-drawer__panel,
.ds-drawer--right.ds-drawer--md .ds-drawer__panel {
  width: 420px;
  max-width: 100vw;
}

.ds-drawer--left.ds-drawer--lg .ds-drawer__panel,
.ds-drawer--right.ds-drawer--lg .ds-drawer__panel {
  width: 560px;
  max-width: 100vw;
}

.ds-drawer--top.ds-drawer--sm .ds-drawer__panel,
.ds-drawer--bottom.ds-drawer--sm .ds-drawer__panel {
  max-height: 30vh;
}

.ds-drawer--top.ds-drawer--md .ds-drawer__panel,
.ds-drawer--bottom.ds-drawer--md .ds-drawer__panel {
  max-height: 50vh;
}

.ds-drawer--top.ds-drawer--lg .ds-drawer__panel,
.ds-drawer--bottom.ds-drawer--lg .ds-drawer__panel {
  max-height: 75vh;
}

/* ============================================
   HEADER
   ============================================ */

.ds-drawer__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--gap-400); /* 16px */
  flex-shrink: 0;
}

.ds-drawer__heading {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100); /* 4px */
  min-width: 0;
}

.ds-drawer__title {
  font-family: var(--font-heading-3-family);
  font-size: var(--font-heading-3-size);
  font-weight: var(--font-heading-3-weight);
  line-height: var(--font-heading-3-line-height);
  letter-spacing: var(--font-heading-3-letter-spacing);
  color: var(--color-text-primary);
  margin: 0;
}

.ds-drawer__description {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  margin: 0;
}

/* Close button — ghost icon button */
.ds-drawer__close {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: var(--radius-pill); /* pill */
  background-color: transparent;
  cursor: pointer;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-drawer__close:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-drawer__close:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-drawer__close-icon {
  --icon-size: var(--icon-size-500);
  line-height: 1;
  color: var(--color-icon-primary);
}

/* ============================================
   BODY
   ============================================ */

.ds-drawer__body {
  flex: 1;
  overflow-y: auto;
  min-height: 0;
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-secondary);
}

/* ============================================
   FOOTER
   ============================================ */

.ds-drawer__footer {
  display: flex;
  justify-content: flex-end;
  gap: var(--gap-200); /* 8px */
  padding-top: var(--padding-150); /* 6px */
  flex-shrink: 0;
}

/* ============================================
   RESPONSIVE
   Side drawers go full-width on narrow screens
   ============================================ */

@media (max-width: 480px) {
  .ds-drawer--left .ds-drawer__panel,
  .ds-drawer--right .ds-drawer__panel {
    width: 100vw;
  }
}

/* ============================================
   REDUCED MOTION
   ============================================ */

@media (prefers-reduced-motion: reduce) {
  .ds-drawer,
  .ds-drawer__panel,
  .ds-drawer__scrim {
    transition: none;
  }
}

'use client';

import React, { useRef, useId } from 'react';
import ReactDOM from 'react-dom';
import './Drawer.css';
import '../../fonts/material-symbols.css';
import { useMounted } from '../../behaviors/useMounted';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';

/** Props owned by Drawer itself — everything else falls through to the panel. */
type DrawerOwnProps = {
  /** Whether the drawer is open */
  open: boolean;
  /** Callback when the drawer requests to close */
  onOpenChange: (open: boolean) => void;
  /**
   * Drawer title.
   * Note: this shadows the native `title` tooltip attribute, which Drawer does not expose.
   */
  title: string;
  /** Optional subtitle under the title */
  description?: string;
  /** Drawer body content */
  children?: React.ReactNode;
  /** Optional footer slot — typically a row of Buttons */
  footer?: React.ReactNode;
  /** Edge the panel slides in from */
  side?: 'left' | 'right' | 'top' | 'bottom';
  /** Panel size along the axis it slides on */
  size?: 'sm' | 'md' | 'lg';
  /** Whether ESC, scrim click, and the close button can dismiss */
  dismissible?: boolean;
  /** Additional CSS classes — applied to the portal container, not the panel */
  className?: string;
};

export interface DrawerProps
  extends DrawerOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof DrawerOwnProps> {}

/**
 * Drawer component — an edge-anchored panel that slides in over the page.
 * Shares Dialog's modal semantics (focus trap, focus restore, scroll lock,
 * ESC/scrim dismissal) but is anchored to a viewport edge, which suits
 * filter panels, detail views, and mobile navigation.
 *
 * Renders through a portal into `document.body`. The forwarded ref and any
 * unrecognised props target the **panel** (the `role="dialog"` element), not the
 * portal container.
 */
export const Drawer = React.forwardRef<HTMLDivElement, DrawerProps>(
  (
    {
      open,
      onOpenChange,
      title,
      description,
      children,
      footer,
      side = 'right',
      size = 'md',
      dismissible = true,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const panelRef = useRef<HTMLDivElement | null>(null);
    const titleId = useId();
    const descId = useId();
    const baseClass = 'ds-drawer';

    /** Keep the internal ref (used by the focus trap) while honouring a forwarded one. */
    const setPanelRef = (node: HTMLDivElement | null) => {
      panelRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    // SSR guard — only render the portal on the client
    const mounted = useMounted();

    // Shared overlay behaviors (src/behaviors/) — see Dialog for the
    // contract. Scrim dismissal stays below: it is this component's own DOM.
    useLayer({ open, dismissOnEscape: dismissible, onDismiss: () => onOpenChange(false) });
    useFocusScope(panelRef, { active: open });
    useScrollLock(open);

    const handleScrimClick = () => {
      if (dismissible) onOpenChange(false);
    };

    const classes = [
      baseClass,
      `${baseClass}--${side}`,
      `${baseClass}--${size}`,
      open ? `${baseClass}--open` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const drawer = (
      <div className={classes}>
        <div className={`${baseClass}__scrim`} onClick={handleScrimClick} />

        <div
          {...rest}
          className={`${baseClass}__panel`}
          ref={setPanelRef}
          role="dialog"
          aria-modal="true"
          aria-labelledby={titleId}
          aria-describedby={description ? descId : rest['aria-describedby']}
          tabIndex={-1}
        >
          <div className={`${baseClass}__header`}>
            <div className={`${baseClass}__heading`}>
              <h2 className={`${baseClass}__title`} id={titleId}>
                {title}
              </h2>
              {description && (
                <p className={`${baseClass}__description`} id={descId}>
                  {description}
                </p>
              )}
            </div>

            {dismissible && (
              <button
                type="button"
                className={`${baseClass}__close`}
                onClick={() => onOpenChange(false)}
                aria-label="Close drawer"
              >
                <span
                  className={`${baseClass}__close-icon material-symbols-rounded`}
                  aria-hidden="true"
                >
                  close
                </span>
              </button>
            )}
          </div>

          {children && (
            // Scrollable when content is long; without a tab stop a keyboard
            // user cannot reach that scroll. The initial-focus query below
            // still prefers a real control, so this does not steal focus.
            <div className={`${baseClass}__body`} tabIndex={0}>
              {children}
            </div>
          )}

          {footer && <div className={`${baseClass}__footer`}>{footer}</div>}
        </div>
      </div>
    );

    if (!mounted) return null;
    return ReactDOM.createPortal(drawer, document.body);
  },
);

Drawer.displayName = 'Drawer';
